import json, math, heapq, random

N = 97
random.seed(12345)

def vp(n, p):
    e = 0
    while n:
        n //= p
        e += n
    return e

def is_prime(x):
    if x < 2: return False
    d = 2
    while d*d <= x:
        if x % d == 0: return False
        d += 1
    return True

def divisors(x):
    res = [x] if x > 1 else []
    d = 2
    while d*d <= x:
        if x % d == 0:
            res.append(d)
            if d*d != x:
                res.append(x//d)
        d += 1
    return res

primes = [p for p in range(2, N+1) if is_prime(p)]
base_items = []
for p in primes:
    base_items += [p] * vp(N, p)

def lpt(items):
    bins = [1] * N
    heap = [(0.0, i, 1) for i in range(N)]
    heapq.heapify(heap)
    for x in items:
        l, i, b = heapq.heappop(heap)
        b *= x
        heapq.heappush(heap, (l + math.log(x), i, b))
    out = [0]*N
    for l, i, b in heap:
        out[i] = b
    return out

def repair(bins):
    bins = bins[:]
    for _ in range(500):
        i = min(range(N), key=lambda k: bins[k])
        if bins[i] >= 28:
            return bins
        best = None  # (score, j, new_j, new_i)
        bi = bins[i]
        di = divisors(bi)
        for j in range(N):
            if j == i:
                continue
            bj = bins[j]
            for d in divisors(bj):
                if d >= 2 and bj // d >= 28:
                    score = min(bj//d, bi*d)
                    if score > bi and (best is None or score > best[0]):
                        best = (score, j, bj//d, bi*d)
            for da in divisors(bj):
                for db in di:
                    if da == db:
                        continue
                    aj = bj // da * db
                    ai = bi // db * da
                    if aj >= 28 and ai > bi:
                        score = min(aj, ai)
                        if score > bi and (best is None or score > best[0]):
                            best = (score, j, aj, ai)
        if best is None:
            return None
        _, j, nj, ni = best
        bins[j] = nj
        bins[i] = ni
    return None

solution = None
for trial in range(3000):
    items = base_items[:]
    random.shuffle(items)
    bins = lpt(items)
    if min(bins) < 28:
        bins = repair(bins)
        if bins is None:
            continue
    if min(bins) >= 28:
        solution = bins
        print('success on trial', trial)
        break

if solution is None:
    raise RuntimeError('no solution found')

prod = 1
for b in solution:
    prod *= b
assert prod == math.factorial(N), 'product mismatch'
assert len(solution) == N
assert min(solution) >= 28
print('OK: min =', min(solution), 'max =', max(solution))
json.dump({'factors': solution}, open('/workdir/answer.json', 'w'))
print('written')
