import json, math, heapq, itertools, time

N = 134
LOW = 39

def primes_upto(n):
    sieve = [True]*(n+1)
    r = []
    for i in range(2, n+1):
        if sieve[i]:
            r.append(i)
            for j in range(i*i, n+1, i):
                sieve[j] = False
    return r

items = []
for p in primes_upto(N):
    e = 0
    k = p
    while k <= N:
        e += N // k
        k *= p
    items.extend([p]*e)

items.sort(reverse=True)
nb = N
prods = [1]*nb
members = [[] for _ in range(nb)]
h = [(0.0, i) for i in range(nb)]
heapq.heapify(h)
for p in items:
    lp, i = heapq.heappop(h)
    prods[i] *= p
    members[i].append(p)
    heapq.heappush(h, (lp + math.log(p), i))

print('LPT min:', min(prods))

def subset_prods(lst, maxk):
    d = {1: ()}
    for k in range(1, maxk+1):
        for combo in itertools.combinations(range(len(lst)), k):
            pr = 1
            for i in combo:
                pr *= lst[i]
            if pr not in d:
                d[pr] = combo
    return sorted(d.items())

def apply_op(b, c, S, T):
    sb = [members[b][i] for i in T]
    sc = [members[c][i] for i in S]
    for i in sorted(T, reverse=True):
        del members[b][i]
    for i in sorted(S, reverse=True):
        del members[c][i]
    members[b].extend(sc)
    members[c].extend(sb)
    pb = 1
    for x in members[b]:
        pb *= x
    pc = 1
    for x in members[c]:
        pc *= x
    prods[b] = pb
    prods[c] = pc

deadline = time.time() + 55
ok = False
steps = 0
while time.time() < deadline:
    steps += 1
    b = min(range(nb), key=lambda i: prods[i])
    if prods[b] >= LOW:
        ok = True
        break
    for maxk in (2, 3):
        sub_b = subset_prods(members[b], maxk - 1 if maxk == 3 else maxk)
        best = None
        for c in range(nb):
            if c == b or not members[c]:
                continue
            sub_c = subset_prods(members[c], maxk)
            for ps, S in sub_c:
                if ps == 1:
                    continue
                for pt, T in sub_b:
                    if ps <= pt:
                        continue
                    newb = prods[b] // pt * ps
                    newc = prods[c] // ps * pt
                    if newb >= LOW and newc >= LOW:
                        score = (min(newb, newc), -(len(S)+len(T)))
                        if best is None or score > best[0]:
                            best = (score, c, S, T)
        if best:
            break
    if not best:
        print('stuck at step', steps, 'min:', prods[b])
        break
    _, c, S, T = best
    apply_op(b, c, S, T)

print('steps:', steps, 'ok:', ok)
print('min:', min(prods))
print('max:', max(prods))
fact = math.factorial(N)
total = 1
for x in prods:
    total *= x
print('count:', len(prods))
print('product equals 134!:', total == fact)
print('all >= 39:', min(prods) >= LOW)
if total == fact and min(prods) >= LOW and len(prods) == N:
    json.dump({'factors': prods}, open('/workdir/answer.json', 'w'))
    print('answer written')
