import json, math
from ortools.sat.python import cp_model

N = 106
def isp(x):
    return x >= 2 and all(x % d for d in range(2, int(x**.5) + 1))

exp = {}
for p in range(2, N + 1):
    if isp(p):
        e = 0; q = p
        while q <= N:
            e += N // q; q *= p
        exp[p] = e

large = []
small = []
for p, e in exp.items():
    (large if p >= 31 else small).extend([p] * e)

m = N - len(large)
print('large tokens:', len(large), 'small tokens:', len(small), 'bins:', m)

S = 10**6
def coeff(p): return math.ceil(S * math.log2(p))
RHS = int(S * math.log2(30))  # floor; safe due to integer-product gap

items = sorted(small, reverse=True)
ns = len(items)
model = cp_model.CpModel()
x = [[model.NewBoolVar(f'x_{i}_{j}') for j in range(m)] for i in range(ns)]
for i in range(ns):
    model.AddExactlyOne(x[i])
for j in range(m):
    model.Add(sum(x[i][j] * coeff(items[i]) for i in range(ns)) >= RHS)
model.Add(x[0][0] == 1)  # tiny symmetry break: largest small token in bin 0

solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 55
solver.parameters.num_search_workers = 8
res = solver.Solve(model)
print('status:', solver.StatusName(res))

if res in (cp_model.OPTIMAL, cp_model.FEASIBLE):
    bins = [[] for _ in range(m)]
    for i in range(ns):
        for j in range(m):
            if solver.Value(x[i][j]):
                bins[j].append(items[i]); break
    factors = [math.prod(b) for b in bins] + large
    assert len(factors) == N, len(factors)
    assert min(factors) >= 30, sorted(factors)[:10]
    assert math.prod(factors) == math.factorial(N)
    json.dump({'factors': sorted(factors)}, open('/workdir/answer.json', 'w'))
    print('WROTE answer.json  min:', min(factors), 'max:', max(factors), 'count:', len(factors))
else:
    print('NO SOLUTION FOUND YET')
