import math, json, heapq
import functools, operator

N = 48
MIN = 13

fact = math.factorial(N)
exp = {}

def add_factor(n):
    p = 2
    while p * p <= n:
        while n % p == 0:
            exp[p] = exp.get(p, 0) + 1
            n //= p
        p += 1
    if n > 1:
        exp[n] = exp.get(n, 0) + 1

for k in range(2, N + 1):
    add_factor(k)

items = []
for p, e in exp.items():
    items.extend([p] * e)

bins = [[] for _ in range(N)]
h = [(0.0, i) for i in range(N)]
heapq.heapify(h)
for x in sorted(items, reverse=True):
    s, i = heapq.heappop(h)
    bins[i].append(x)
    heapq.heappush(h, (s + math.log(x), i))

def repair():
    for _ in range(100000):
        bad = [i for i in range(N) if math.prod(bins[i]) < MIN]
        if not bad:
            return True
        i = bad[0]
        pi = math.prod(bins[i])
        moved = False
        for j in range(N):
            if j == i:
                continue
            pj = math.prod(bins[j])
            for x in sorted(set(bins[j]), reverse=True):
                if pj // x >= MIN and pi * x >= MIN:
                    bins[j].remove(x)
                    bins[i].append(x)
                    moved = True
                    break
            if moved:
                break
        if not moved:
            for j in range(N):
                if j == i:
                    continue
                pj = math.prod(bins[j])
                done = False
                for x in set(bins[j]):
                    for y in set(bins[i]):
                        if (pi // y) * x >= MIN and (pj // x) * y >= MIN:
                            bins[j].remove(x); bins[i].append(x)
                            bins[i].remove(y); bins[j].append(y)
                            done = True; moved = True
                            break
                    if done:
                        break
                if moved:
                    break
        if not moved:
            return False
    return False

ok = repair()
factors = [math.prod(b) for b in bins]
print('repair ok:', ok)
print('count:', len(factors), 'min:', min(factors))
assert len(factors) == N
assert all(isinstance(x, int) and x >= MIN for x in factors)
assert functools.reduce(operator.mul, factors, 1) == fact
with open('/workdir/answer.json', 'w') as fh:
    json.dump({'factors': sorted(factors)}, fh)
print('WROTE answer')
print(sorted(factors))
