sieve = [True]*s
sieve[0] = sieve[1] = False
primes = []
for i in range(2, s):
    if sieve[i]:
        primes.append(i)
        for j in range(i*i, s, i):
            sieve[j] = False
for p in primes:
    pp = p*p
    for m in range(pp, LIM+1, pp):
        nsf[m] = True

verts = [a for a in range(1, N+1) if nsf[a*a+1]]
print('vertices:', verts)
adj = {a: set() for a in verts}
for a in verts:
    for b in verts:
        if nsf[a*b+1]:
            adj[a].add(b)
best = []
def bk(R, P, X):
    global best
    if not P and not X:
        if len(R) > len(best):
            best = list(R)
        return
    if len(R) + len(P) <= len(best):
        return
    for v in list(P):
        bk(R+[v], P & adj[v], X & adj[v])
        P = P - {v}
        X = X | {v}
bk([], set(verts), set())
best = sorted(best)
print('clique size:', len(best))
print('clique:', best)
ok = all(nsf[a*b+1] for a in best for b in best)
print('verify all pairs non-squarefree:', ok)
ans = sorted(best)[:30]
if 5 <= len(ans) <= 30 and ok:
    json.dump({'A': ans}, open('/workdir/answer.json', 'w'))
    print('written:', ans)
